// v4.9: 状态门控与席位点（与大厅面板同一套规则）—— full/playing/closed 置灰不可加入；
// live 行（Lunar/梨子湖实时大厅）无 TTL，显示「在线」而不是倒计时。
const roomState = (r) => {
  const st = String(r.status || '');
  if (st === 'full') return '已满';
  if (st === 'playing') return '对局中';
  if (st === 'closed') return '已关闭';
  if (!r.live && !(Number(r.left) > 0)) return '已过期';
  return '';
};
const roomJoinable = (r) => {
  const st = String(r.status || '');
  if (st === 'full' || st === 'playing' || st === 'closed') return false;
  return r.live ? true : Number(r.left) > 0;
};
const seatDots = (r) => {
  const cap = Number(r.capacity);
  if (!(cap > 0) || cap > 8) return null;
  let occ = Number(r.occupied) >= 0 ? Number(r.occupied) : (Number(r.humans) >= 0 ? Number(r.humans) : 0);
  if (occ > cap) occ = cap;
  let s = '';
  for (let i = 0; i < cap; i++) s += i < occ ? '●' : '○';
  return { text: s, title: `席位 ${occ}/${cap}` };
};

${rooms.map((r) => {
  const state = roomState(r);
  const can = roomJoinable(r);
  const seats = seatDots(r);
  return html`<div key=${(r.host || r.serverId || '?') + '#' + r.code} style=${rowStyle + (can ? '' : ';opacity:.6')}>
    <b class="num" style="color:#4ed8af;min-width:2.6em">${r.code}</b>
    <span style="min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;opacity:.8">${r.server || '—'}</span>
    ${seats ? html`<span class="num" title=${seats.title} style="opacity:.7;white-space:nowrap;letter-spacing:.02em">${seats.text}</span>` : null}
    <span style="flex:1;min-width:0;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;opacity:.55"
      title=${r.note}>${r.note || ''}</span>
    <span class="num" style=${'white-space:nowrap;color:' + ((r.live || Number(r.left) > 60) ? '#8a9a93' : '#e06c5a')}>${state || (r.live ? '在线' : '剩 ' + left(r.left))}</span>
    ${can
      ? html`<${Button} variant="secondary" size="sm" onClick=${() => onJoin(r)}>加入<//>`
      : html`<${Button} variant="secondary" size="sm" disabled=${true}>${state || '不可加入'}<//>`}
  </div>`;
})}
